/**
 * A língua do gato — porte de `componentes/viz/lingua_gato.js`.
 *
 * A língua é coberta de espículas de queratina viradas para trás, e cada uma tem
 * a ponta em CONCHA — não é um espinho, é uma colherinha. Na inclinação certa
 * elas entram no pelo, desfazem o nó e ainda levam saliva até a pele, que é como
 * o gato se refresca. Retas demais não penetram; deitadas demais prendem o fio.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import { type EstadoDaViz, infoDe, numeroDe, paleta, rodape, titulo } from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const FIOS = 14;
const ESPICULAS = 11;

const linguaGato: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const inclinacao = Math.max(0, numeroDe(valores, 'a', 0));
    const ok = info.ok === true;
    // 0 é espícula em pé; quanto maior, mais deitada para trás.
    const angulo = (inclinacao / 100) * (Math.PI / 2.4);

    titulo(ctx, L, A, 'A língua que é um pente');

    // Os fios de pelo: embaraçados à esquerda; à direita, já penteados quando a
    // inclinação fecha. O contraste dentro da mesma cena é o que ensina.
    ctx.strokeStyle = cor.fraco;
    ctx.lineWidth = 1.5;
    for (let i = 0; i < FIOS; i++) {
      const x = ((i + 0.5) / FIOS) * L;
      const limpo = ok && x > L * 0.45;

      ctx.beginPath();
      ctx.moveTo(x, A * 0.16);
      for (let y = A * 0.16; y < A * 0.62; y += 6) {
        const onda = limpo ? 0 : Math.sin(y * 0.06 + i) * 5;
        ctx.lineTo(x + onda, y);
      }
      ctx.stroke();
    }

    // A língua.
    ctx.fillStyle = '#d98aa0';
    ctx.beginPath();
    ctx.moveTo(0, A * 0.76);
    ctx.quadraticCurveTo(L * 0.5, A * 0.66, L, A * 0.76);
    ctx.lineTo(L, A);
    ctx.lineTo(0, A);
    ctx.closePath();
    ctx.fill();

    // As espículas, com a ponta em concha.
    const baseY = A * 0.72;
    ctx.lineWidth = 3;
    ctx.lineCap = 'round';
    ctx.strokeStyle = ok ? '#c05a76' : '#a8536b';
    for (let i = 0; i < ESPICULAS; i++) {
      const bx = ((i + 0.5) / ESPICULAS) * L;
      const by = baseY + Math.sin(bx * 0.04) * 6;
      const comprimento = 26;
      const tx = bx + Math.sin(angulo) * comprimento;
      const ty = by - Math.cos(angulo) * comprimento;

      ctx.beginPath();
      ctx.moveTo(bx, by);
      ctx.lineTo(tx, ty);
      ctx.lineTo(tx - Math.cos(angulo) * 5, ty - Math.sin(angulo) * 5);
      ctx.stroke();
    }

    // A saliva subindo pelas espículas — o segundo trabalho da língua.
    if (ok) {
      ctx.fillStyle = cor.azulClaro;
      for (let i = 0; i < 5; i++) {
        const fase = (t * 0.7 + i / 5) % 1;
        const x = ((i + 0.5) / 5) * L;
        ctx.globalAlpha = 0.8 * (1 - fase * 0.5);
        ctx.beginPath();
        ctx.arc(x, baseY - fase * A * 0.5, 2.5, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    }

    rodape(
      ctx,
      L,
      A,
      ok,
      'Pelo desembaraçado e saliva na pele ✔',
      'Ajuste a inclinação das espículas.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default linguaGato;
